Json::Value CollectionResources::toJson() const
{
    Json::Value ret;
    if(getCollectionId())
    {
        ret["collection_id"]=getValueOfCollectionId();
    }
    else
    {
        ret["collection_id"]=Json::Value();
    }
    if(getResourceId())
    {
        ret["resource_id"]=getValueOfResourceId();
    }
    else
    {
        ret["resource_id"]=Json::Value();
    }
    if(getNotes())
    {
        ret["notes"]=getValueOfNotes();
    }
    else
    {
        ret["notes"]=Json::Value();
    }
    if(getCreatedBy())
    {
        ret["created_by"]=getValueOfCreatedBy();
    }
    else
    {
        ret["created_by"]=Json::Value();
    }
    if(getCreatedAt())
    {
        ret["created_at"]=getCreatedAt()->toDbStringLocal();
    }
    else
    {
        ret["created_at"]=Json::Value();
    }
    if(getModifiedBy())
    {
        ret["modified_by"]=getValueOfModifiedBy();
    }
    else
    {
        ret["modified_by"]=Json::Value();
    }
    if(getModifiedAt())
    {
        ret["modified_at"]=getModifiedAt()->toDbStringLocal();
    }
    else
    {
        ret["modified_at"]=Json::Value();
    }
    return ret;
}

std::string CollectionResources::toString() const
{
    return toJson().toStyledString();
}

